use super::{
    Listener,
    body::{Counters, Payload, RequestBody, ResponseBody},
    io::Connection,
    prepared::{PreparedTarget, Value},
    request::{FailurePhase, failure_response, strip_hop_headers, upstream_error},
};
use crate::{
    model::{Action as RouteAction, PathMatch, Route, RuntimeSnapshot},
    proxy::{
        Proxy,
        completion::{Completion, UpstreamCompletion},
        error,
    },
};
use bytes::Bytes;
use http::header;
use http_body_util::Full;
use hyper::body::Body as _;
use hyper::{Request, Response};
use std::{
    sync::{Arc, atomic::Ordering},
    time::Instant,
};

static TRACEPARENT: http::HeaderName = http::HeaderName::from_static("traceparent");

pub(super) enum Action {
    Proxy(PreparedTarget),
    Reply {
        status: http::StatusCode,
        headers: http::HeaderMap,
        body: Bytes,
    },
}

impl Action {
    pub fn prepare(route: &Route, target: Option<&PreparedTarget>) -> anyhow::Result<Option<Self>> {
        let s = &route.settings;
        // Only policy-free routes can omit the original request view. A later
        // snapshot must re-evaluate this gate before publishing its execution plan.
        if route.script.is_some()
            || route.tenant.is_some()
            || route.rollout.is_some()
            || s.gateway.is_some()
            || s.access_log.is_some()
            || !s.identity.trusted.is_empty()
            || !s.identity.access.is_empty()
            || s.traffic.rate.is_some()
            || s.traffic.concurrency.is_some()
            || s.security.jwt.is_some()
            || s.security.external.is_some()
            || s.security.mtls.mode != crate::security::mtls::Mode::Off
            || s.https_redirect_port.is_some()
            || s.compression.gzip > 0
            || s.compression.brotli > 0
            || s.request_headers.iter().any(|(_, v)| v.contains('$'))
            || s.response_headers.iter().any(|h| h.value.contains('$'))
        {
            return Ok(None);
        }
        Ok(match &route.action {
            RouteAction::Proxy { uri: None, .. }
                if target.is_some_and(|b| {
                    matches!(
                        b.backend.backend.options.balance,
                        crate::backend::Balance::RoundRobin
                            | crate::backend::Balance::LeastConnections
                    ) && s.upstream.protocol == crate::upstream::Protocol::Http1
                }) =>
            {
                Some(Self::Proxy(target.unwrap().clone()))
            }
            RouteAction::Return { status, text } if !text.contains('$') => {
                let redirect = (300..400).contains(status) && !text.is_empty();
                let reply = super::responses::reply(
                    *status,
                    if redirect {
                        String::new()
                    } else {
                        text.clone()
                    },
                    redirect.then(|| text.clone()),
                );
                let (parts, _) = reply.into_parts();
                Some(Self::Reply {
                    status: parts.status,
                    headers: parts.headers,
                    body: if redirect || [204, 304].contains(status) {
                        Bytes::new()
                    } else {
                        Bytes::copy_from_slice(text.as_bytes())
                    },
                })
            }
            _ => None,
        })
    }
}

pub(super) struct Selected {
    snapshot: Arc<RuntimeSnapshot>,
    route: Arc<Route>,
    prepared_route: usize,
    started: Instant,
}

pub(super) fn select(listener: &Listener, request: &Request<Payload>) -> Option<Selected> {
    if request.version() != http::Version::HTTP_11
        || request.method() == http::Method::CONNECT
        || listener.shared.telemetry.trace_ratio.is_some()
        || request.headers().contains_key(&TRACEPARENT)
        || request.headers().contains_key(header::UPGRADE)
        || request
            .headers()
            .get(header::CONTENT_TYPE)
            .is_some_and(|v| v.as_bytes().starts_with(b"application/grpc"))
    {
        return None;
    }
    let started = Instant::now();
    let snapshot = listener.shared.snapshot.load_full();
    let prepared = snapshot.hyper.as_ref()?;
    if snapshot.gateway.is_some() || !prepared.has_plain {
        return None;
    }
    crate::proxy::validate_connection_header(request.headers()).ok()?;
    let host =
        crate::proxy::request_host_parts(request.headers(), request.uri(), request.version())
            .ok()?;
    let path = crate::proxy::normalized_path_view(request.uri().path()).ok()?;
    let (h, r) = snapshot.route_position(listener.address, &host, &path)?;
    let prepared_route = prepared.route_positions[h][r];
    let route = prepared.routes[prepared_route].route.clone();
    prepared.routes[prepared_route].plain.as_ref()?;
    if prepared.slash_redirects
        && !path.ends_with('/')
        && !matches!(route.matcher, PathMatch::Exact(_))
    {
        let slash = format!("{path}/");
        if snapshot
            .route(listener.address, &host, &slash)
            .is_some_and(|r| {
                matches!(&r.matcher, PathMatch::NginxPrefix(p) if p == &slash)
                    && matches!(r.action, RouteAction::Proxy { .. })
            })
        {
            return None;
        }
    }
    Some(Selected {
        snapshot,
        route,
        prepared_route,
        started,
    })
}

pub(super) struct Guard {
    pub proxy: Proxy,
    pub counts: Counters,
    upload_counts: Option<Arc<Counters>>,
    pub snapshot: Arc<RuntimeSnapshot>,
    pub route: Arc<Route>,
    prepared_route: usize,
    pub started: Instant,
    pub _permit: crate::runtime::RequestPermit,
    backend_attempted: bool,
    pub upstream_started: Option<Instant>,
    pub lease: Option<crate::backend::Lease>,
    pub error: Option<Box<pingora::Error>>,
    pub status: u16,
    pub io_failure: Arc<std::sync::atomic::AtomicU8>,
    finished: bool,
}

impl Guard {
    pub fn finish(&mut self, delivered: bool) {
        if self.finished {
            return;
        }
        self.finished = true;
        if !delivered && self.error.is_none() {
            let kind = match self.io_failure.load(Ordering::Relaxed) {
                1 => pingora::ErrorType::ReadTimedout,
                2 => pingora::ErrorType::WriteTimedout,
                _ => pingora::ErrorType::ConnectionClosed,
            };
            self.error = Some(
                pingora::Error::explain(kind, "downstream did not complete response").into_down(),
            );
        }
        let backend = match &self.route.action {
            RouteAction::Proxy { backend, .. } => Some(backend.as_str()),
            _ => None,
        };
        let telemetry = &self.proxy.shared.telemetry;
        let metrics = backend.and_then(|name| {
            let Action::Proxy(target) = self.snapshot.hyper.as_ref()?.routes[self.prepared_route]
                .plain
                .as_ref()?
            else {
                return None;
            };
            target.backend.metrics(telemetry, name)
        });
        let label = backend.map(|b| {
            if metrics.is_some() {
                b
            } else {
                telemetry.label("backend", b)
            }
        });
        let completion = Completion {
            version: http::Version::HTTP_11,
            status: self.status,
            request_bytes: self
                .upload_counts
                .as_ref()
                .map_or(0, |counts| counts.request.load(Ordering::Relaxed))
                as usize,
            response_bytes: self.counts.response.load(Ordering::Relaxed) as usize,
            error: self.error.as_deref(),
        };
        let duration = self.proxy.record_completion(
            self.started,
            self.lease.as_ref().and_then(|lease| {
                Some(UpstreamCompletion {
                    lease,
                    label: label?,
                    duration_metric: metrics.map(|m| &m.duration),
                    started: self.upstream_started?,
                })
            }),
            &completion,
        );
        let upstream_failed = self
            .error
            .as_ref()
            .is_some_and(|e| e.esource() == &pingora::ErrorSource::Upstream);
        if let Some(metrics) = metrics {
            telemetry.route_completed(Some(&self.route), self.status, duration.as_secs_f64(), None);
            if self.backend_attempted {
                metrics.completed(upstream_failed || self.status >= 500);
            }
        } else {
            telemetry.completed(
                Some(&self.route),
                backend.filter(|_| self.backend_attempted),
                self.status,
                duration.as_secs_f64(),
                upstream_failed || self.status >= 500,
                None,
            );
        }
        if let Some(e) = &self.error {
            if upstream_failed {
                self.proxy.shared.telemetry.upstream_errors.inc();
            }
            log::warn!(
                "request failed route={} backend={} upstream={:?} version={}: {e}",
                self.route.id,
                backend.unwrap_or("-"),
                self.lease.as_ref().map(|l| l.address),
                self.snapshot.version
            );
        }
    }
}
impl Drop for Guard {
    fn drop(&mut self) {
        self.finish(false);
    }
}

pub(super) async fn serve(
    listener: &Listener,
    request: Request<Payload>,
    connection: Arc<Connection>,
    selected: Selected,
    permit: crate::runtime::RequestPermit,
) -> Response<ResponseBody> {
    let mut guard = Box::new(Guard {
        proxy: Proxy {
            shared: listener.shared.clone(),
            listener: listener.address,
            tls: connection.tls,
        },
        counts: Counters::default(),
        upload_counts: None,
        snapshot: selected.snapshot,
        route: selected.route,
        prepared_route: selected.prepared_route,
        started: selected.started,
        _permit: permit,
        backend_attempted: false,
        upstream_started: None,
        lease: None,
        error: None,
        status: 499,
        io_failure: connection.failure.clone(),
        finished: false,
    });
    connection.read_timeout_ms.store(
        guard
            .route
            .settings
            .client_body_timeout
            .as_millis()
            .min(u64::MAX as u128) as u64,
        Ordering::Relaxed,
    );
    connection.write_timeout_ms.store(
        guard
            .route
            .settings
            .send_timeout
            .as_millis()
            .min(u64::MAX as u128) as u64,
        Ordering::Relaxed,
    );
    let head = request.method() == http::Method::HEAD;
    let mut response = match forward(listener, request, &mut guard).await {
        Ok(response) => response,
        Err(failure) => {
            let response = failure_response(&failure);
            guard.error = Some(failure);
            response
        }
    };
    guard.status = response.status().as_u16();
    let prepared = &guard.snapshot.hyper.as_ref().unwrap().routes[guard.prepared_route];
    for (name, value, always) in &prepared.response_headers {
        if (*always || [200, 201, 204, 206, 301, 302, 303, 304, 307, 308].contains(&guard.status))
            && let Value::Constant(value) = value
            && !value.is_empty()
        {
            response.headers_mut().append(name.clone(), value.clone());
        }
    }
    if head || [204, 304].contains(&guard.status) {
        *response.body_mut() = Payload::Full(Full::new(Bytes::new()));
    }
    if guard.error.is_some()
        || listener.shared.telemetry.draining.get() != 0
        || guard.route.settings.keepalive.is_zero()
    {
        response
            .headers_mut()
            .insert(header::CONNECTION, http::HeaderValue::from_static("close"));
    }
    let (parts, body) = response.into_parts();
    Response::from_parts(parts, ResponseBody::plain(body, guard, connection))
}

async fn forward(
    listener: &Listener,
    mut request: Request<Payload>,
    guard: &mut Guard,
) -> pingora::Result<Response<Payload>> {
    let settings = &guard.route.settings;
    if settings.max_body > 0
        && request
            .headers()
            .get(header::CONTENT_LENGTH)
            .and_then(|v| v.to_str().ok())
            .and_then(|v| v.parse::<u64>().ok())
            .is_some_and(|n| n > settings.max_body)
    {
        return Err(error(413, "request body too large"));
    }
    let prepared = &guard.snapshot.hyper.as_ref().unwrap().routes[guard.prepared_route];
    let selected = match prepared.plain.as_ref().unwrap() {
        Action::Reply {
            status,
            headers,
            body,
        } => {
            let mut response = Response::new(Payload::Full(Full::new(body.clone())));
            *response.status_mut() = *status;
            *response.headers_mut() = headers.clone();
            return Ok(response);
        }
        Action::Proxy(target) => target,
    };
    let RouteAction::Proxy { backend: name, .. } = &guard.route.action else {
        unreachable!()
    };
    guard.backend_attempted = true;
    let lease = selected
        .backend
        .backend
        .select("")
        .ok_or_else(|| error(503, "no ready endpoint or backend budget exhausted"))?;
    let address = lease.address;
    guard.lease = Some(lease);
    guard.upstream_started = Some(Instant::now());
    let te = request
        .headers()
        .get(header::TE)
        .is_some_and(|v| v.as_bytes().eq_ignore_ascii_case(b"trailers"));
    let trailer = request.headers().get(header::TRAILER).cloned();
    strip_hop_headers(request.headers_mut());
    request
        .headers_mut()
        .insert(header::HOST, selected.backend.host.clone());
    for (name, value) in &prepared.request_headers {
        if let Value::Constant(value) = value {
            if value.is_empty() {
                request.headers_mut().remove(name);
            } else {
                request.headers_mut().insert(name.clone(), value.clone());
            }
        }
    }
    if te {
        request
            .headers_mut()
            .insert(header::TE, http::HeaderValue::from_static("trailers"));
    }
    if let Some(trailer) = trailer {
        request.headers_mut().insert(header::TRAILER, trailer);
    }
    if let Some(sender) = request
        .extensions_mut()
        .get_mut::<hyper::ext::SendInformational>()
    {
        sender.forward(|response| strip_hop_headers(response.headers_mut()));
    }
    let request = request.map(|body| {
        if body.is_end_stream() {
            return RequestBody::empty();
        }
        let counts = Arc::new(Counters::default());
        guard.upload_counts = Some(counts.clone());
        RequestBody::new(
            body,
            counts,
            settings.max_body,
            settings.client_body_timeout,
        )
    });
    let result = selected
        .inline(listener.worker)
        .request(request, address)
        .await;
    let (mut response, received) = result.map_err(|failure| {
        match guard
            .upload_counts
            .as_ref()
            .map_or(0, |counts| counts.request_error.load(Ordering::Relaxed))
        {
            1 => error(413, "request body too large"),
            2 => error(400, "incomplete request body").into_down(),
            3 => error(408, "request body timed out").into_down(),
            _ => upstream_error(
                &failure,
                if failure.is_connect() {
                    FailurePhase::Connect
                } else {
                    FailurePhase::Request
                },
            ),
        }
    })?;
    let seconds = received
        .duration_since(guard.upstream_started.unwrap())
        .as_secs_f64();
    let telemetry = &listener.shared.telemetry;
    match selected.backend.metrics(telemetry, name) {
        Some(metrics) => metrics.headers.observe(seconds),
        None => telemetry
            .traffic
            .upstream_headers
            .with_label_values(&[telemetry.label("backend", name)])
            .observe(seconds),
    }
    if response.status() == http::StatusCode::SWITCHING_PROTOCOLS {
        return Err(error(502, "unsolicited upstream upgrade"));
    }
    let trailers: Vec<_> = response
        .headers()
        .get_all(header::TRAILER)
        .iter()
        .cloned()
        .collect();
    strip_hop_headers(response.headers_mut());
    for trailer in trailers {
        response.headers_mut().append(header::TRAILER, trailer);
    }
    Ok(response)
}

sources.src/proxy/hyper/prepared.rs:
use super::{ProxyClient, upstream::Connector};
use crate::{
    model::{Action, Route, RuntimeSnapshot},
    proxy::{Context, error, expand},
};
use anyhow::{Context as _, Result};
use http::{HeaderName, HeaderValue, uri::Authority};
use hyper_util::{
    client::legacy::Client,
    rt::{TokioExecutor, TokioTimer},
};
use sha2::{Digest, Sha256};
use std::{
    collections::HashMap,
    net::SocketAddr,
    sync::{Arc, OnceLock},
};

pub(crate) struct Prepared {
    pub acceptors: HashMap<SocketAddr, openssl::ssl::SslAcceptor>,
    #[cfg(feature = "http3")]
    pub quic: HashMap<SocketAddr, quinn::ServerConfig>,
    #[cfg(feature = "http3")]
    pub http3_all: bool,
    pub has_plain: bool,
    pub slash_redirects: bool,
    pub pool_size: usize,
    pub workers: usize,
    pub idle_budget: hyper_util::client::legacy::IdlePoolBudget,
    // Route IDs need not be unique (exact and prefix locations can share a path).
    // These identities remain valid while the owning snapshot retains its routes.
    route_ids: HashMap<(SocketAddr, usize), usize>,
    pub(super) route_positions: Vec<Vec<usize>>,
    // Indices belong to this immutable snapshot; requests retain its owner across reloads.
    pub(super) routes: Vec<PreparedRoute>,
    clients: HashMap<ClientKey, Arc<Clients>>,
    tls_keys: HashMap<SocketAddr, [u8; 32]>,
}

pub(super) struct PreparedRoute {
    pub route: Arc<Route>,
    pub plain: Option<super::plain::Action>,
    pub targets: HashMap<String, PreparedTarget>,
    pub request_headers: Vec<(HeaderName, Value)>,
    pub response_headers: Vec<(HeaderName, Value, bool)>,
    // Dynamic templates retain the complete original view; fixed routes capture
    // only fields read by policy and completion, before outbound header edits.
    pub original_headers: Option<Vec<HeaderName>>,
}

#[derive(Clone)]
pub(super) struct PreparedTarget {
    pub backend: Arc<PreparedBackend>,
    clients: Arc<Clients>,
}

#[derive(Clone, PartialEq, Eq, Hash)]
struct ClientKey {
    name: String,
    listener: SocketAddr,
    connect: std::time::Duration,
    read: std::time::Duration,
    write: std::time::Duration,
    keepalive: std::time::Duration,
    transport: [u8; 32],
    backend: usize,
}

struct Clients {
    builder: hyper_util::client::legacy::Builder,
    connector: Connector,
    workers: Vec<OnceLock<ProxyClient>>,
    websocket_connector: Option<Connector>,
    websocket_workers: Vec<OnceLock<ProxyClient>>,
    inline: Vec<OnceLock<Arc<super::inline::Client>>>,
    observer: super::inline::Observer,
    idle_budget: hyper_util::client::legacy::IdlePoolBudget,
    maximum: usize,
    keepalive: std::time::Duration,
}

impl PreparedTarget {
    pub fn inline(&self, worker: usize) -> &Arc<super::inline::Client> {
        let clients = &self.clients;
        clients.inline[worker].get_or_init(|| {
            super::inline::Client::new(
                clients.connector.clone(),
                clients.observer.clone(),
                clients.idle_budget.clone(),
                clients.maximum,
                clients.keepalive,
            )
        })
    }
    pub fn websocket_client(&self, worker: usize) -> &ProxyClient {
        match &self.clients.websocket_connector {
            Some(connector) => self.clients.websocket_workers[worker]
                .get_or_init(|| self.clients.builder.build(connector.clone())),
            None => self.client(worker),
        }
    }
    pub fn client(&self, worker: usize) -> &ProxyClient {
        // HTTP/1 pools stay on their reactor; HTTP/2 and ALPN auto retain one
        // shared multiplexer. Transport validation stays on the control plane.
        let worker = if self.clients.workers.len() == 1 {
            0
        } else {
            worker
        };
        self.clients.workers[worker]
            .get_or_init(|| self.clients.builder.build(self.clients.connector.clone()))
    }
}

pub(super) struct PreparedBackend {
    pub backend: Arc<crate::backend::Backend>,
    pub host: HeaderValue,
    authorities: HashMap<SocketAddr, Authority>,
    metrics: OnceLock<Option<crate::telemetry::BackendMetrics>>,
}

impl PreparedBackend {
    pub fn metrics(
        &self,
        telemetry: &crate::telemetry::Telemetry,
        name: &str,
    ) -> Option<&crate::telemetry::BackendMetrics> {
        self.metrics
            .get_or_init(|| crate::telemetry::BackendMetrics::new(telemetry, name))
            .as_ref()
    }

    pub fn authority(&self, address: SocketAddr) -> Result<Authority, http::uri::InvalidUri> {
        match self.authorities.get(&address) {
            Some(authority) => Ok(authority.clone()),
            // DNS maintenance can introduce endpoints after this snapshot was prepared.
            None => address.to_string().parse(),
        }
    }
}

pub(super) enum Value {
    Constant(HeaderValue),
    Variable(String),
}

impl Value {
    fn new(value: &str) -> Result<Self> {
        Ok(if value.contains('$') {
            Self::Variable(value.into())
        } else {
            Self::Constant(value.parse()?)
        })
    }

    pub fn expand(&self, ctx: &Context, host: &str) -> pingora::Result<HeaderValue> {
        match self {
            Self::Constant(value) => Ok(value.clone()),
            Self::Variable(value) => expand(value, ctx, false, host)
                .parse()
                .map_err(|_| error(500, "invalid expanded header")),
        }
    }
}

impl Prepared {
    pub fn new(
        snapshot: &RuntimeSnapshot,
        previous: Option<&Self>,
        pool_size: usize,
        workers: usize,
        idle_budget: hyper_util::client::legacy::IdlePoolBudget,
        telemetry: &Arc<crate::telemetry::Telemetry>,
        #[cfg(feature = "http3")] http3_all: bool,
    ) -> Result<Self> {
        let mut clients: HashMap<ClientKey, Arc<Clients>> = HashMap::new();
        let backends: HashMap<_, _> = snapshot
            .backends
            .iter()
            .map(|(name, backend)| {
                let authorities = backend
                    .endpoints
                    .iter()
                    .map(|endpoint| Ok((endpoint.address, endpoint.address.to_string().parse()?)))
                    .collect::<Result<_>>()?;
                Ok((
                    name.as_str(),
                    Arc::new(PreparedBackend {
                        backend: backend.clone(),
                        host: backend.host_header.parse()?,
                        authorities,
                        metrics: OnceLock::new(),
                    }),
                ))
            })
            .collect::<Result<_>>()?;
        let mut routes = Vec::new();
        let mut route_ids = HashMap::new();
        for host in &snapshot.hosts {
            for route in &host.routes {
                let settings = &route.settings;
                if route_ids.contains_key(&(host.listener, Arc::as_ptr(route) as usize)) {
                    continue;
                }
                let mut names = std::collections::BTreeSet::new();
                if route.script.is_some() {
                    names.extend(route.allowed_backends.values().cloned());
                }
                if let Action::Proxy { backend, .. } = &route.action {
                    names.insert(backend.clone());
                }
                if let Some(gateway) = &settings.gateway {
                    names.extend(gateway.backends.iter().filter_map(|(name, _)| name.clone()));
                }
                if let Some(rollout) = &route.rollout {
                    names.extend(rollout.backends.values().cloned());
                }
                let mut targets = HashMap::new();
                for name in names {
                    let Some(backend) = backends.get(name.as_str()) else {
                        continue;
                    };
                    let transport = if settings.gateway.is_some() {
                        &backend.backend.profile
                    } else {
                        &settings.upstream
                    };
                    // A reused backend is the same validated configuration, including
                    // endpoint membership. Changed credentials or transport never share pools.
                    let key = ClientKey {
                        name: name.clone(),
                        listener: host.listener,
                        connect: settings.connect_timeout,
                        read: settings.read_timeout,
                        write: settings.write_timeout,
                        keepalive: settings.keepalive,
                        transport: Sha256::digest(serde_json::to_vec(transport)?).into(),
                        backend: Arc::as_ptr(&backend.backend) as usize,
                    };
                    let client = if let Some(client) = clients
                        .get(&key)
                        .or_else(|| previous.and_then(|p| p.clients.get(&key)))
                    {
                        client.clone()
                    } else {
                        let client_workers =
                            if transport.protocol == crate::upstream::Protocol::Http1 {
                                workers
                            } else {
                                1
                            };
                        let mut builder = Client::builder(TokioExecutor::new());
                        builder
                            .pool_timer(TokioTimer::new())
                            .pool_idle_timeout(settings.keepalive)
                            .pool_max_idle_per_host(pool_size / client_workers)
                            .shared_idle_budget(idle_budget.clone())
                            .retry_canceled_requests(false)
                            .http2_only(transport.protocol == crate::upstream::Protocol::Http2);
                        let telemetry = telemetry.clone();
                        let label = name.clone();
                        let observed = backend.clone();
                        let observer: super::inline::Observer = Arc::new(move |reused, elapsed| {
                            if let Some(metrics) = observed.metrics(&telemetry, &label) {
                                metrics.connect[usize::from(reused)].observe(elapsed.as_secs_f64());
                                return;
                            }
                            let label = telemetry.label("backend", &label);
                            telemetry
                                .traffic
                                .upstream_connect
                                .with_label_values(&[label, if reused { "true" } else { "false" }])
                                .observe(elapsed.as_secs_f64());
                        });
                        builder.connection_observer({
                            let observer = observer.clone();
                            move |reused, elapsed| observer(reused, elapsed)
                        });
                        let connector = Connector::new(
                            settings.connect_timeout,
                            settings.read_timeout,
                            settings.write_timeout,
                            transport,
                            &backend.backend,
                        )?;
                        let websocket_connector =
                            if transport.protocol == crate::upstream::Protocol::Auto {
                                let mut transport = transport.clone();
                                transport.protocol = crate::upstream::Protocol::Http1;
                                Some(Connector::new(
                                    settings.connect_timeout,
                                    settings.read_timeout,
                                    settings.write_timeout,
                                    &transport,
                                    &backend.backend,
                                )?)
                            } else {
                                None
                            };
                        Arc::new(Clients {
                            inline: (0..client_workers).map(|_| OnceLock::new()).collect(),
                            observer,
                            idle_budget: idle_budget.clone(),
                            maximum: pool_size / client_workers,
                            keepalive: settings.keepalive,
                            builder,
                            connector,
                            workers: (0..client_workers).map(|_| OnceLock::new()).collect(),
                            websocket_workers: if websocket_connector.is_some() {
                                (0..workers).map(|_| OnceLock::new()).collect()
                            } else {
                                Vec::new()
                            },
                            websocket_connector,
                        })
                    };
                    clients.entry(key).or_insert_with(|| client.clone());
                    targets.insert(
                        name,
                        PreparedTarget {
                            backend: backend.clone(),
                            clients: client,
                        },
                    );
                }
                let request_headers = settings
                    .request_headers
                    .iter()
                    .map(|(name, value)| Ok((name.parse()?, Value::new(value)?)))
                    .collect::<Result<_>>()?;
                let response_headers = settings
                    .response_headers
                    .iter()
                    .map(|header| {
                        Ok((
                            header.name.parse()?,
                            Value::new(&header.value)?,
                            header.always,
                        ))
                    })
                    .collect::<Result<_>>()?;
                let backend = match &route.action {
                    Action::Proxy { backend, .. } => Some(
                        backends
                            .get(backend.as_str())
                            .context("missing prepared Hyper backend")?
                            .clone(),
                    ),
                    _ => None,
                };
                let original_headers = original_headers(route, backend.as_deref());
                let plain = super::plain::Action::prepare(
                    route,
                    match &route.action {
                        Action::Proxy { backend, .. } => targets.get(backend),
                        _ => None,
                    },
                )?;
                route_ids.insert((host.listener, Arc::as_ptr(route) as usize), routes.len());
                routes.push(PreparedRoute {
                    route: route.clone(),
                    plain,
                    targets,
                    request_headers,
                    response_headers,
                    original_headers,
                });
            }
        }
        let route_positions = snapshot
            .hosts
            .iter()
            .map(|host| {
                host.routes
                    .iter()
                    .map(|route| route_ids[&(host.listener, Arc::as_ptr(route) as usize)])
                    .collect()
            })
            .collect();
        let mut acceptors = HashMap::new();
        let mut tls_keys = HashMap::new();
        #[cfg(feature = "http3")]
        let mut quic = HashMap::new();
        for listener in snapshot.listeners.iter().filter(|l| l.tls) {
            let key = tls_key(snapshot, listener)?;
            let prior = previous.filter(|p| p.tls_keys.get(&listener.address) == Some(&key));
            let acceptor = match prior.and_then(|p| p.acceptors.get(&listener.address)) {
                Some(acceptor) => acceptor.clone(),
                None => super::tls::acceptor(snapshot, listener)?,
            };
            acceptors.insert(listener.address, acceptor);
            tls_keys.insert(listener.address, key);
            #[cfg(feature = "http3")]
            if http3_all
                || snapshot
                    .hosts
                    .iter()
                    .filter(|h| h.listener == listener.address)
                    .flat_map(|h| &h.routes)
                    .any(|r| r.settings.http3)
            {
                let config = match prior.and_then(|p| p.quic.get(&listener.address)) {
                    Some(config) => config.clone(),
                    None => super::h3_tls::config(snapshot, listener.address)?,
                };
                quic.insert(listener.address, config);
            }
        }
        Ok(Self {
            acceptors,
            #[cfg(feature = "http3")]
            quic,
            #[cfg(feature = "http3")]
            http3_all,
            has_plain: routes.iter().any(|r| r.plain.is_some()),
            slash_redirects: snapshot.hosts.iter().flat_map(|h| &h.routes).any(|r| {
                matches!(&r.matcher, crate::model::PathMatch::NginxPrefix(p) if p.len() > 1 && p.ends_with('/'))
                    && matches!(r.action, Action::Proxy { .. })
            }),
            pool_size,
            workers,
            routes,
            route_ids,
            route_positions,
            idle_budget,
            clients,
            tls_keys,
        })
    }

    pub(super) fn route(&self, listener: SocketAddr, route: &Arc<Route>) -> &PreparedRoute {
        &self.routes[self.route_index(listener, route)]
    }

    pub(super) fn route_index(&self, listener: SocketAddr, route: &Arc<Route>) -> usize {
        self.route_ids[&(listener, Arc::as_ptr(route) as usize)]
    }
}

fn tls_key(snapshot: &RuntimeSnapshot, listener: &crate::model::Listener) -> Result<[u8; 32]> {
    let mut hosts: Vec<_> = snapshot
        .certificates
        .iter()
        .filter(|h| h.listener == listener.address)
        .collect();
    hosts.sort_by(|a, b| a.name.cmp(&b.name));
    let mut hash = Sha256::new();
    hash.update(serde_json::to_vec(listener)?);
    for host in hosts {
        hash.update(serde_json::to_vec(&(
            &host.name,
            host.ingress,
            host.default,
            &host.client_auth,
        ))?);
        if let Some(cert) = &host.certificate {
            let chain: Vec<_> = std::iter::once(&cert.leaf)
                .chain(cert.chain.iter())
                .map(|c| c.to_der())
                .collect::<Result<_, _>>()?;
            hash.update(serde_json::to_vec(&chain)?);
            hash.update(cert.key.private_key_to_der()?);
        } else {
            hash.update(b"withdrawn");
        }
    }
    Ok(hash.finalize().into())
}

fn original_headers(route: &Route, backend: Option<&PreparedBackend>) -> Option<Vec<HeaderName>> {
    let settings = &route.settings;
    if route.script.is_some()
        || route.tenant.is_some()
        || route.rollout.is_some()
        || settings.gateway.is_some()
        || settings.security.jwt.is_some()
        || settings.security.external.is_some()
        || settings.compression.gzip > 0
        || settings.compression.brotli > 0
        || matches!(route.action, Action::Static)
        || backend.is_some_and(|b| {
            matches!(
                b.backend.options.balance,
                crate::backend::Balance::Sticky(_)
            )
        })
    {
        return None;
    }
    if settings
        .request_headers
        .iter()
        .any(|(_, v)| v.contains('$'))
        || settings
            .response_headers
            .iter()
            .any(|h| h.value.contains('$'))
        || matches!(&route.action, Action::Return { text, .. } if text.contains('$'))
    {
        return None;
    }
    let mut names = vec![http::header::CONTENT_TYPE];
    if settings.access_log.is_some() {
        names.extend([http::header::REFERER, http::header::USER_AGENT]);
    }
    let mut key = |key: &crate::traffic::Key| {
        let name = match key {
            crate::traffic::Key::Header(name) => name.parse().expect("validated header key"),
            crate::traffic::Key::Cookie(_) => http::header::COOKIE,
            _ => return,
        };
        if !names.contains(&name) {
            names.push(name);
        }
    };
    if let Some(rate) = &settings.traffic.rate {
        key(&rate.key);
    }
    if let Some(concurrency) = &settings.traffic.concurrency {
        key(&concurrency.key);
    }
    if let Some(backend) = backend
        && let crate::backend::Balance::Hash(hash) = &backend.backend.options.balance
    {
        key(hash);
    }
    Some(names)
}

