use super::{Limits, Shared};
#[cfg(feature = "hyper-experimental")]
use anyhow::Context;
use anyhow::Result;
use pingora::{
    server::{Server, configuration::ServerConf},
    services::ServiceWithDependents,
};
use std::sync::Arc;
#[cfg(feature = "hyper-experimental")]
use std::time::Duration;

pub(super) struct Host {
    pub configuration: Arc<ServerConf>,
    engine: Engine,
}

enum Engine {
    Pingora(Server),
    #[cfg(feature = "hyper-experimental")]
    Native {
        services: Vec<Box<dyn ServiceWithDependents>>,
        shared: Arc<Shared>,
        limits: Limits,
    },
}

impl Host {
    pub fn new(conf: ServerConf, shared: Arc<Shared>, limits: &Limits) -> Self {
        #[cfg(feature = "hyper-experimental")]
        if shared.experimental_hyper {
            return Self {
                configuration: Arc::new(conf),
                engine: Engine::Native {
                    services: Vec::new(),
                    shared,
                    limits: limits.clone(),
                },
            };
        }
        let mut server = Server::new_with_opt_and_conf(None, conf);
        let max = limits.max_inflight;
        server.set_graceful_shutdown_check(move || shared.requests.available_permits() == max);
        Self {
            configuration: server.configuration.clone(),
            engine: Engine::Pingora(server),
        }
    }

    pub fn add_service(&mut self, service: impl ServiceWithDependents + 'static) {
        match &mut self.engine {
            Engine::Pingora(server) => {
                server.add_service(service);
            }
            #[cfg(feature = "hyper-experimental")]
            Engine::Native { services, .. } => services.push(Box::new(service)),
        }
    }

    pub fn bootstrap(&mut self) {
        match &mut self.engine {
            Engine::Pingora(server) => server.bootstrap(),
            #[cfg(feature = "hyper-experimental")]
            Engine::Native { .. } => {}
        }
    }

    pub fn run(self) -> Result<()> {
        match self.engine {
            Engine::Pingora(server) => {
                server.run(Default::default());
                Ok(())
            }
            #[cfg(feature = "hyper-experimental")]
            Engine::Native {
                services,
                shared,
                limits,
            } => run(services, shared, limits),
        }
    }
}

#[cfg(feature = "hyper-experimental")]
fn metric_thread_hooks(builder: &mut tokio::runtime::Builder, range: std::ops::Range<usize>) {
    // Blocking threads retire and restart; returning slots prevents their
    // replacements from consuming another listener's assigned range.
    let slots = Arc::new(std::sync::Mutex::new(range.rev().collect::<Vec<_>>()));
    let starting = slots.clone();
    builder.on_thread_start(move || {
        let slot = starting.lock().unwrap().pop().unwrap_or(0);
        crate::telemetry::sharded::register_worker(slot);
    });
    builder.on_thread_stop(move || {
        let slot = crate::telemetry::sharded::unregister_worker();
        if slot != 0 {
            slots.lock().unwrap().push(slot);
        }
    });
}

#[cfg(feature = "hyper-experimental")]
fn metric_service_slots(name: &str, threads: usize) -> usize {
    // background_service() prefixes the name exposed by ServiceWithDependents.
    let name = name.strip_prefix("BG ").unwrap_or(name);
    if name.starts_with("hyper-") {
        1
    } else if name.starts_with("http3-") {
        1 + (if threads > 1 { threads } else { 0 }) + (16 / threads).clamp(1, 2)
    } else {
        0
    }
}

#[cfg(feature = "hyper-experimental")]
fn run(
    services: Vec<Box<dyn ServiceWithDependents>>,
    shared: Arc<Shared>,
    limits: Limits,
) -> Result<()> {
    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()?;
    runtime
        .block_on(async move {
            #[cfg(unix)]
            let mut terminate =
                tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate())?;
            #[cfg(unix)]
            let mut quit = tokio::signal::unix::signal(tokio::signal::unix::SignalKind::quit())?;
            #[cfg(unix)]
            let mut interrupt =
                tokio::signal::unix::signal(tokio::signal::unix::SignalKind::interrupt())?;
            #[cfg(unix)]
            let _hangup = tokio::signal::unix::signal(tokio::signal::unix::SignalKind::hangup())?;
            let (shutdown, watch) = tokio::sync::watch::channel(false);
            let (finish, finished) = tokio::sync::watch::channel(false);
            let stopped = Arc::new(std::sync::atomic::AtomicUsize::new(0));
            let mut workers = Vec::new();
            let _wakeup_probe = shared.telemetry.data_plane.enable(
                Duration::from_secs(limits.hyper_worker_stall_timeout_seconds),
                limits.hyper_wakeup_probe,
            )?;
            let heartbeats: Vec<_> = services
                .iter()
                .map(|s| shared.telemetry.data_plane.register(s.name().to_owned()))
                .collect();
            crate::telemetry::sharded::register_worker(0);
            let mut next_metric_slot = 0;
            for (mut service, heartbeat) in services.into_iter().zip(heartbeats) {
                let name = service.name().to_owned();
                let threads = service.threads().unwrap_or(limits.threads);
                let metric_slots = metric_service_slots(&name, threads);
                let metric_slot = if metric_slots > 0 {
                    next_metric_slot
                } else {
                    0
                };
                next_metric_slot += metric_slots;
                let runtime_slots = metric_slots.saturating_sub(1);
                let watch = watch.clone();
                let mut finished = finished.clone();
                let stopped = stopped.clone();
                let worker =
                    std::thread::Builder::new()
                        .name(name)
                        .spawn(move || -> Result<()> {
                            crate::telemetry::sharded::register_worker(metric_slot);
                            let mut builder = if threads == 1 {
                                let mut builder = tokio::runtime::Builder::new_current_thread();
                                // Bound I/O deferral without polling the reactor after
                                // every few proxy exchanges under sustained load.
                                builder.event_interval(32);
                                builder
                            } else {
                                let mut builder = tokio::runtime::Builder::new_multi_thread();
                                builder.worker_threads(threads);
                                builder
                            };
                            metric_thread_hooks(
                                &mut builder,
                                metric_slot + 1..metric_slot + 1 + runtime_slots,
                            );
                            let runtime = builder
                                .enable_all()
                                .max_blocking_threads((16 / threads).clamp(1, 2))
                                .build()?;
                            let (ready, _) = tokio::sync::watch::channel(false);
                            runtime.block_on(async {
                                let heartbeat = tokio::spawn(heartbeat.run());
                                service
                                    .start_service(
                                        #[cfg(unix)]
                                        None,
                                        watch,
                                        1,
                                        pingora::services::ServiceReadyNotifier::new(ready),
                                    )
                                    .await;
                                heartbeat.abort();
                            });
                            stopped.fetch_add(1, std::sync::atomic::Ordering::Release);
                            // A shared H2 client can be driven by a reactor whose
                            // listener has drained before another listener's RPCs.
                            // Keep all reactors alive until every service drains.
                            runtime.block_on(async {
                                let _ = finished.changed().await;
                            });
                            runtime.shutdown_timeout(Duration::from_secs(1));
                            Ok(())
                        })?;
                workers.push(worker);
            }
            let mut unexpected = false;
            let signal = async {
                #[cfg(unix)]
                tokio::select! {
                    _ = interrupt.recv() => {},
                    _ = terminate.recv() => {},
                    _ = quit.recv() => {},
                }
                #[cfg(not(unix))]
                tokio::signal::ctrl_c().await?;
                Ok::<_, std::io::Error>(())
            };
            tokio::pin!(signal);
            loop {
                tokio::select! {
                    result = &mut signal => { result?; break; }
                    _ = tokio::time::sleep(Duration::from_millis(100)) => {
                        if stopped.load(std::sync::atomic::Ordering::Acquire) != 0
                            || workers.iter().any(|worker| worker.is_finished()) {
                            unexpected = true;
                            break;
                        }
                    }
                }
            }
            shared.telemetry.draining.set(1);
            let grace =
                tokio::time::Instant::now() + Duration::from_secs(limits.shutdown_grace_seconds);
            while shared.requests.available_permits() < limits.max_inflight
                && tokio::time::Instant::now() < grace
            {
                tokio::time::sleep(Duration::from_millis(25)).await;
            }
            let _ = shutdown.send(true);
            let deadline =
                tokio::time::Instant::now() + Duration::from_secs(limits.shutdown_timeout_seconds);
            while stopped.load(std::sync::atomic::Ordering::Acquire) < workers.len()
                && tokio::time::Instant::now() < deadline
            {
                tokio::time::sleep(Duration::from_millis(25)).await;
            }
            let _ = finish.send(true);
            let deadline = tokio::time::Instant::now() + Duration::from_secs(2);
            while workers.iter().any(|worker| !worker.is_finished())
                && tokio::time::Instant::now() < deadline
            {
                tokio::time::sleep(Duration::from_millis(25)).await;
            }
            for worker in workers {
                if worker.is_finished() {
                    worker
                        .join()
                        .map_err(|_| anyhow::anyhow!("service thread panicked"))??;
                } else {
                    log::warn!("service exceeded shutdown deadline");
                }
            }
            anyhow::ensure!(!unexpected, "a runtime service stopped unexpectedly");
            Ok(())
        })
        .context("native Hyper runtime")
}

#[cfg(all(test, feature = "hyper-experimental"))]
mod tests {
    use super::*;

    #[test]
    fn background_listeners_reserve_distinct_metric_slots() {
        use pingora::services::background::{BackgroundService, background_service};
        struct Idle;
        #[async_trait::async_trait]
        impl BackgroundService for Idle {}
        let services = [
            background_service("control", Idle),
            background_service("hyper-127.0.0.1:8080-0", Idle),
            background_service("hyper-127.0.0.1:8080-1", Idle),
            background_service("hyper-127.0.0.1:8081-0", Idle),
            background_service("hyper-127.0.0.1:8081-1", Idle),
            background_service("http3-127.0.0.1:8443", Idle),
        ];
        let mut next = 0;
        let ranges: Vec<_> = services
            .iter()
            .map(|service| {
                let count = metric_service_slots(service.name(), 2);
                let range = next..next + count;
                next += count;
                range
            })
            .collect();
        assert_eq!(ranges, [0..0, 0..1, 1..2, 2..3, 3..4, 4..9]);
        assert_eq!(metric_service_slots("BG http3-127.0.0.1:8443", 1), 3);
    }

    #[test]
    fn retired_blocking_threads_reuse_their_assigned_metric_slot() {
        let mut builder = tokio::runtime::Builder::new_current_thread();
        builder
            .max_blocking_threads(1)
            .thread_keep_alive(Duration::from_millis(10));
        metric_thread_hooks(&mut builder, 1..2);
        let runtime = builder.build().unwrap();
        let mut threads = std::collections::HashSet::new();
        for _ in 0..4 {
            let (thread, slot) = runtime.block_on(async {
                tokio::task::spawn_blocking(|| {
                    let slot = crate::telemetry::sharded::unregister_worker();
                    crate::telemetry::sharded::register_worker(slot);
                    (std::thread::current().id(), slot)
                })
                .await
                .unwrap()
            });
            assert_eq!(slot, 1);
            threads.insert(thread);
            std::thread::sleep(Duration::from_millis(100));
        }
        assert!(threads.len() > 1, "the test must exercise a retired worker");
    }
}

sources.src/telemetry.rs:
mod controller;
#[cfg(feature = "hyper-experimental")]
mod data_plane;
mod request;
mod runtime;
pub mod sharded;
#[cfg(feature = "hyper-experimental")]
pub(crate) use request::BackendMetrics;
pub(crate) use request::RouteMetrics;
pub(crate) mod traffic;
use anyhow::Result;
use prometheus::{
    Encoder, Histogram, HistogramVec, IntCounter, IntCounterVec, IntGauge, IntGaugeVec, Registry,
    TextEncoder,
};
use std::{
    path::PathBuf,
    sync::{
        Arc,
        atomic::{AtomicBool, Ordering},
    },
};

pub struct Telemetry {
    #[cfg(feature = "hyper-experimental")]
    pub(crate) data_plane: Arc<data_plane::DataPlane>,
    pub traffic: traffic::Traffic,
    pub controller: controller::Controller,
    pub config_updated: prometheus::Gauge,
    pub config_update_seconds: HistogramVec,
    pub otlp: Option<crate::otlp::Exporter>,
    pub traces: Option<crate::otlp::Exporter>,
    pub trace_ratio: Option<f64>,
    route_requests: sharded::CounterVec,
    grpc_requests: sharded::CounterVec,
    route_duration: sharded::HistogramVec,
    backend_requests: sharded::CounterVec,
    status_counts: Vec<std::sync::OnceLock<sharded::Counter>>,
    unmatched: std::sync::OnceLock<RouteMetrics>,
    labels: std::sync::RwLock<
        std::collections::BTreeMap<&'static str, std::collections::BTreeSet<String>>,
    >,
    pub healthy: AtomicBool,
    pub ready: AtomicBool,
    pub(crate) listeners_ready: AtomicBool,
    pub draining: IntGauge,
    pub registry: Registry,
    pub requests: sharded::CounterVec,
    pub duration: sharded::Histogram,
    pub plugin_errors: IntCounter,
    pub plugin_calls: IntCounter,
    pub plugin_duration: Histogram,
    pub upstream_errors: IntCounter,
    pub reload_errors: IntCounter,
    pub reloads: IntCounter,
    pub version: IntGauge,
    pub dropped_logs: IntCounter,
    pub config_degraded: IntGauge,
    pub checkpoint_healthy: IntGauge,
    pub checkpoint_errors: IntCounter,
    pub report_errors: IntCounter,
    pub config_info: IntGaugeVec,
    pub rejected: IntCounterVec,
    pub upstream_ejections: IntCounter,
    pub rollbacks: IntCounter,
    pub mirror_results: IntCounterVec,
    tenant_rejected: IntCounterVec,
    label_overflow: IntCounterVec,
    pub files: Arc<crate::logging::FileLogs>,
    pub certificate_expiry: IntGaugeVec,
    pub certificate_valid: IntGaugeVec,
    pub control_reloads: IntCounter,
    pub control_reload_errors: IntCounter,
}
impl Telemetry {
    pub fn new(otlp: crate::otlp::Options) -> Result<Arc<Self>> {
        Self::with_workers(otlp, 1)
    }

    pub fn with_workers(otlp: crate::otlp::Options, workers: usize) -> Result<Arc<Self>> {
        let workers = workers.max(1);
        let registry = Registry::new();
        #[cfg(feature = "hyper-experimental")]
        let data_plane = data_plane::DataPlane::new(&registry)?;
        let draining = prometheus::register_int_gauge_with_registry!(
            "rgnix_draining",
            "Process has begun connection draining",
            registry
        )?;
        #[cfg(target_os = "linux")]
        registry.register(Box::new(
            prometheus::process_collector::ProcessCollector::for_self(),
        ))?;
        let traffic = traffic::Traffic::with_workers(&registry, workers)?;
        let controller = controller::Controller::new(&registry)?;
        let config_updated = prometheus::register_gauge_with_registry!(
            "rgnix_config_last_success_timestamp_seconds",
            "Last successful snapshot publication, including standalone startup",
            registry
        )?;
        let config_update_seconds = prometheus::register_histogram_vec_with_registry!(
            "rgnix_config_update_seconds",
            "Configuration build and publication duration",
            &["source", "result"],
            registry
        )?;
        let label_overflow = prometheus::register_int_counter_vec_with_registry!(
            "rgnix_metric_label_overflow_total",
            "Metric observations assigned to the overflow label",
            &["kind"],
            registry
        )?;
        let certificate_expiry = IntGaugeVec::new(
            prometheus::Opts::new(
                "rgnix_certificate_expiry_timestamp_seconds",
                "Certificate expiration time",
            ),
            &["listener", "host"],
        )?;
        let certificate_valid = IntGaugeVec::new(
            prometheus::Opts::new(
                "rgnix_certificate_valid",
                "Certificate time and hostname validity",
            ),
            &["listener", "host"],
        )?;
        registry.register(Box::new(certificate_expiry.clone()))?;
        registry.register(Box::new(certificate_valid.clone()))?;
        let control_reloads = IntCounter::new(
            "rgnix_control_reloads_total",
            "Access and tenant policy updates",
        )?;
        let control_reload_errors = IntCounter::new(
            "rgnix_control_reload_errors_total",
            "Rejected access and tenant policy updates",
        )?;
        registry.register(Box::new(control_reloads.clone()))?;
        registry.register(Box::new(control_reload_errors.clone()))?;
        anyhow::ensure!(
            otlp.trace_sample_ratio.is_finite() && (0.0..=1.0).contains(&otlp.trace_sample_ratio),
            "trace sample ratio must be 0..1"
        );
        let traces = crate::otlp::Exporter::start_traces(otlp.clone(), &registry)?;
        let trace_ratio = traces.as_ref().map(|_| otlp.trace_sample_ratio);
        let otlp = crate::otlp::Exporter::start(otlp, &registry)?;
        let grpc_requests = sharded::CounterVec::new(
            prometheus::Opts::new(
                "rgnix_grpc_requests_total",
                "Completed RPCs by route and gRPC status",
            ),
            &["route", "grpc_status"],
            workers,
        )?;
        registry.register(Box::new(grpc_requests.clone()))?;
        let route_requests = sharded::CounterVec::new(
            prometheus::Opts::new(
                "rgnix_route_requests_total",
                "Completed requests by configured route",
            ),
            &["route", "status_class"],
            workers,
        )?;
        let route_duration = sharded::HistogramVec::new(
            prometheus::HistogramOpts::new(
                "rgnix_route_request_seconds",
                "Request duration by configured route",
            ),
            &["route"],
            workers,
        )?;
        let backend_requests = sharded::CounterVec::new(
            prometheus::Opts::new(
                "rgnix_backend_requests_total",
                "Completed requests by configured backend",
            ),
            &["backend", "result"],
            workers,
        )?;
        registry.register(Box::new(route_requests.clone()))?;
        registry.register(Box::new(route_duration.clone()))?;
        registry.register(Box::new(backend_requests.clone()))?;
        let tenant_rejected = IntCounterVec::new(
            prometheus::Opts::new(
                "rgnix_namespace_rejections_total",
                "Requests rejected by namespace budgets",
            ),
            &["namespace", "resource"],
        )?;
        registry.register(Box::new(tenant_rejected.clone()))?;
        let rollbacks = IntCounter::new(
            "rgnix_traffic_rollbacks_total",
            "Automatic traffic rollbacks",
        )?;
        let mirror_results = IntCounterVec::new(
            prometheus::Opts::new("rgnix_mirror_requests_total", "Mirror outcomes"),
            &["result"],
        )?;
        registry.register(Box::new(rollbacks.clone()))?;
        registry.register(Box::new(mirror_results.clone()))?;
        let upstream_ejections = IntCounter::new(
            "rgnix_upstream_ejections_total",
            "Endpoints excluded after repeated transport failures",
        )?;
        registry.register(Box::new(upstream_ejections.clone()))?;
        let config_info = IntGaugeVec::new(
            prometheus::Opts::new("rgnix_config_info", "Active configuration fingerprint"),
            &["sha256"],
        )?;
        let rejected = IntCounterVec::new(
            prometheus::Opts::new(
                "rgnix_rejected_requests_total",
                "Requests rejected by process resource budgets",
            ),
            &["budget"],
        )?;
        registry.register(Box::new(config_info.clone()))?;
        registry.register(Box::new(rejected.clone()))?;
        let requests = sharded::CounterVec::new(
            prometheus::Opts::new("rgnix_requests_total", "Completed requests"),
            &["status"],
            workers,
        )?;
        let duration = sharded::Histogram::with_opts(
            prometheus::HistogramOpts::new("rgnix_request_seconds", "Request duration"),
            workers,
        )?;
        let plugin_errors = IntCounter::new(
            "rgnix_plugin_errors_total",
            "Plugin traps or invalid actions",
        )?;
        let plugin_calls = IntCounter::new(
            "rgnix_plugin_calls_total",
            "Request and response plugin evaluations",
        )?;
        let plugin_duration = Histogram::with_opts(
            prometheus::HistogramOpts::new(
                "rgnix_plugin_seconds",
                "Plugin evaluation duration including request instantiation",
            )
            .buckets(vec![
                0.00001, 0.000025, 0.00005, 0.0001, 0.00025, 0.001, 0.01, 0.1,
            ]),
        )?;
        let upstream_errors = IntCounter::new("rgnix_upstream_errors_total", "Upstream errors")?;
        let reload_errors = IntCounter::new(
            "rgnix_reload_errors_total",
            "Rejected configuration updates",
        )?;
        let reloads = IntCounter::new("rgnix_reloads_total", "Published configuration updates")?;
        let version = IntGauge::new("rgnix_config_version", "Current configuration version")?;
        let dropped_logs = IntCounter::new(
            "rgnix_access_logs_dropped_total",
            "Access records dropped by queue overflow or file I/O failure",
        )?;
        let config_degraded = IntGauge::new(
            "rgnix_config_diagnostics",
            "Current configuration diagnostics",
        )?;
        let checkpoint_healthy = IntGauge::new(
            "rgnix_checkpoint_healthy",
            "Last checkpoint persistence succeeded",
        )?;
        let checkpoint_errors = IntCounter::new(
            "rgnix_checkpoint_errors_total",
            "Checkpoint persistence failures",
        )?;
        let report_errors = IntCounter::new(
            "rgnix_report_errors_total",
            "Kubernetes reporting failures or timeouts",
        )?;
        registry.register(Box::new(config_degraded.clone()))?;
        registry.register(Box::new(checkpoint_healthy.clone()))?;
        registry.register(Box::new(requests.clone()))?;
        registry.register(Box::new(duration.clone()))?;
        registry.register(Box::new(plugin_duration.clone()))?;
        for counter in [
            &plugin_errors,
            &plugin_calls,
            &upstream_errors,
            &reload_errors,
            &reloads,
            &dropped_logs,
            &checkpoint_errors,
            &report_errors,
        ] {
            registry.register(Box::new(counter.clone()))?;
        }
        registry.register(Box::new(version.clone()))?;
        let files = crate::logging::FileLogs::start(&registry, dropped_logs.clone())?;
        Ok(Arc::new(Self {
            traffic,
            controller,
            config_updated,
            config_update_seconds,
            label_overflow,
            certificate_expiry,
            certificate_valid,
            control_reloads,
            control_reload_errors,
            otlp,
            traces,
            trace_ratio,
            route_requests,
            grpc_requests,
            route_duration,
            backend_requests,
            status_counts: (0..1000).map(|_| std::sync::OnceLock::new()).collect(),
            unmatched: Default::default(),
            labels: Default::default(),
            #[cfg(feature = "hyper-experimental")]
            data_plane,
            healthy: AtomicBool::new(true),
            draining,
            ready: AtomicBool::new(false),
            listeners_ready: AtomicBool::new(true),
            registry,
            requests,
            duration,
            plugin_errors,
            plugin_calls,
            plugin_duration,
            upstream_errors,
            reload_errors,
            reloads,
            version,
            dropped_logs,
            config_degraded,
            checkpoint_healthy,
            checkpoint_errors,
            report_errors,
            config_info,
            rejected,
            upstream_ejections,
            rollbacks,
            mirror_results,
            tenant_rejected,
            files,
        }))
    }
    pub fn access(&self, path: PathBuf, line: String) {
        self.files.access(path, line);
    }
    pub(crate) fn label<'a>(&self, kind: &'static str, value: &'a str) -> &'a str {
        let label = self.resolve_label(kind, value);
        if label != value {
            self.label_overflow.with_label_values(&[kind]).inc();
        }
        label
    }
    fn resolve_label<'a>(&self, kind: &'static str, value: &'a str) -> &'a str {
        if self
            .labels
            .read()
            .unwrap_or_else(|e| e.into_inner())
            .get(kind)
            .is_some_and(|labels| labels.contains(value))
        {
            return value;
        }
        let mut labels = self.labels.write().unwrap_or_else(|e| e.into_inner());
        if labels
            .get(kind)
            .is_some_and(|labels| labels.contains(value))
            || labels.values().map(|values| values.len()).sum::<usize>() < 2048
        {
            labels.entry(kind).or_default().insert(value.to_owned());
            value
        } else {
            "_overflow"
        }
    }
    pub(crate) fn namespace_rejected(&self, namespace: &str, resource: &str) {
        let namespace = self.label("namespace", namespace);
        self.tenant_rejected
            .with_label_values(&[namespace, resource])
            .inc();
    }
    pub(crate) fn observe_runtime(
        shared: &Arc<crate::runtime::Shared>,
        limits: &crate::runtime::Limits,
    ) -> Result<()> {
        shared
            .telemetry
            .registry
            .register(Box::new(runtime::RuntimeCollector::new(shared, limits)?))?;
        Ok(())
    }
    pub fn completed(
        &self,
        route: Option<&crate::model::Route>,
        backend: Option<&str>,
        status: u16,
        seconds: f64,
        failed: bool,
        grpc_status: Option<u16>,
    ) {
        self.route_completed(route, status, seconds, grpc_status);
        if let Some(backend) = backend {
            let backend = self.label("backend", backend);
            self.backend_requests
                .with_label_values(&[backend, if failed { "error" } else { "ok" }])
                .inc();
        }
    }

    pub(crate) fn route_completed(
        &self,
        route: Option<&crate::model::Route>,
        status: u16,
        seconds: f64,
        grpc_status: Option<u16>,
    ) {
        let metrics = match route {
            Some(route) => route
                .metrics
                .get_or_init(|| RouteMetrics::new(self, &route.id)),
            None => self
                .unmatched
                .get_or_init(|| RouteMetrics::new(self, "_unmatched")),
        };
        metrics.completed(self, status, seconds, grpc_status);
    }
    pub(crate) fn runtime_healthy(&self) -> bool {
        #[cfg(feature = "hyper-experimental")]
        if !self.data_plane.healthy() {
            return false;
        }
        true
    }
    pub(crate) fn is_ready(&self) -> bool {
        self.ready.load(Ordering::Acquire)
            && self.listeners_ready.load(Ordering::Acquire)
            && self.draining.get() == 0
            && self.runtime_healthy()
    }
    pub fn render(&self, path: &str) -> (u16, Vec<u8>, &'static str) {
        match path {
            "/healthz" => {
                if self.healthy.load(Ordering::Acquire) && self.runtime_healthy() {
                    (200, b"ok\n".to_vec(), "text/plain")
                } else {
                    (503, b"controller failed\n".to_vec(), "text/plain")
                }
            }
            "/readyz" => {
                if self.is_ready() {
                    (200, b"ready\n".to_vec(), "text/plain")
                } else {
                    (503, b"not ready\n".to_vec(), "text/plain")
                }
            }
            "/metrics" => {
                #[cfg(feature = "hyper-experimental")]
                self.data_plane.update_metrics();
                let mut output = vec![];
                match TextEncoder::new().encode(&self.registry.gather(), &mut output) {
                    Ok(()) => (200, output, "text/plain; version=0.0.4"),
                    Err(_) => (500, vec![], "text/plain"),
                }
            }
            _ => (404, b"not found\n".to_vec(), "text/plain"),
        }
    }
}

